<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\Admin\StoreRoleRequest; use App\Http\Requests\Admin\UpdateRoleRequest; use App\Repositories\RoleRepository; use App\Services\RoleService; use Inertia\Inertia; use Spatie\Permission\Models\Permission; use Spatie\Permission\Models\Role;
class RoleController extends Controller { public function __construct(private RoleRepository $repo,private RoleService $service){} public function index(){return Inertia::render('Admin/Roles/Index',['roles'=>$this->repo->all()]);} private function groups(){return Permission::orderBy('name')->get()->groupBy(fn($p)=>explode('.',$p->name)[0]);} public function create(){return Inertia::render('Admin/Roles/Create',['permissionGroups'=>$this->groups()]);} public function store(StoreRoleRequest $r){$this->service->create($r->validated());return redirect()->route('admin.roles.index')->with('success','Role created successfully.');} public function edit(Role $role){$role->load('permissions');return Inertia::render('Admin/Roles/Edit',['role'=>$role,'permissionGroups'=>$this->groups(),'selectedPermissions'=>$role->permissions->pluck('name')]);} public function update(UpdateRoleRequest $r,Role $role){$this->service->update($role,$r->validated());return redirect()->route('admin.roles.index')->with('success','Role updated successfully.');} public function destroy(Role $role){$this->service->delete($role);return back()->with('success','Role deleted successfully.');} }
